// [MEDIUM_PRIORITY] PERFORMANCE: String Concatenation optimized
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.cognitive.engineimport com.roshan.persona.cognitive.model.CognitiveConfigimport com.roshan.persona.cognitive.model.UncertaintyAction/** * NOUS — Uncertainty Awareness (Module 7 v2 — Step 7.2, P1). * * Handles cases where NOUS can't reason confidently. Prevents hallucinated * reasoning — if NOUS doesn't know, it says so. * * ## Confidence → Action mapping (per strategy v2 §"UncertaintyAwareness") * * | Confidence | Action | Example | * |-----------|--------|---------| * | ≥ 0.7 | [UncertaintyAction.Answer] | "I recommend the train." | * | 0.3 – 0.7 | [UncertaintyAction.AskFollowUp] | "I need more context. Could you clarify..." | * | < 0.3 | [UncertaintyAction.AdmitUnknown] | "I don't know enough about this. Let me search." | * * The thresholds come from [CognitiveConfig]: *  - [CognitiveConfig.confidenceCautiousThreshold] (0.7) — above this, answer. *  - [CognitiveConfig.confidenceDeferThreshold] (0.3) — below this, admit unknown. * * ## Integration * * Called by [com.roshan.persona.cognitive.engine.CognitiveFacade] AFTER * reasoning but BEFORE sending the response to the user. If the action is * not [UncertaintyAction.Answer], the facade intercepts and handles it. * * ## Why this matters * * Without uncertainty awareness, NOUS would confidently answer every question * — even ones it has no knowledge about. This leads to hallucinations and * erodes user trust. Admitting "I don't know" is better than a confident * wrong answer. * * @see <a href="docs/strategy/module-7-cognitive-strategy-v2.md">§UncertaintyAwareness</a> */class UncertaintyAwareness(    private val config: CognitiveConfig = CognitiveConfig(),) {    /**     * Decide what to do based on [confidence].     *     * @param confidence the reasoning confidence (0.0–1.0).     * @param query the original user query (for follow-up / search).     * @return the action to take.     */    fun handle(confidence: Float, query: String): UncertaintyAction {        require(confidence in 0f..1f) { "confidence must be in [0,1], got $confidence" }        return when {            confidence >= config.confidenceCautiousThreshold -> {                UncertaintyAction.Answer            }            confidence >= config.confidenceDeferThreshold -> {                // Medium confidence — ask a follow-up question.                val question = generateFollowUp(query)                UncertaintyAction.AskFollowUp(question)            }            else -> {                // Very low confidence — admit unknown + suggest search.                UncertaintyAction.AdmitUnknown(                    "I don't know enough about this. Let me search for more information."                )            }        }    }    /**     * Check if NOUS should search the web before answering.     *     * Returns true when confidence is below [CognitiveConfig.confidenceDeferThreshold].     * The [com.roshan.persona.cognitive.engine.CognitiveFacade] uses this to     * decide whether to trigger a web search before reasoning.     */    fun shouldSearchWeb(confidence: Float): Boolean {        require(confidence in 0f..1f) { "confidence must be in [0,1]" }        return confidence < config.confidenceDeferThreshold    }    /**     * Generate a follow-up question for medium-confidence scenarios.     *     * The question guides the user to provide the missing context that     * would boost NOUS's confidence above the cautious threshold.     */    private fun generateFollowUp(query: String): String {        // For v1, use a generic follow-up. v3 will use LLM to generate        // a context-specific question.        return "I need a bit more context to give you a good answer. " +            "Could you tell me more about what you're looking for?"    }}